"""Authenticated passphrase encryption for key export/import bundles.

A bundle is an opaque, single base64 token. Its plaintext carries one full key
record (label, every version with its algorithm, timestamps, public and private
material, the current-version pointer and the revocation fields). The key is
derived from the passphrase with a memory-hard KDF and the payload is sealed
with AES-256-GCM, so a wrong passphrase and any tampering both fail
authentication rather than yielding partial plaintext.
"""

import base64
import json
import os

from cryptography.exceptions import InvalidTag
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.kdf.scrypt import Scrypt

from .crypto import SUPPORTED_ALGORITHMS

FORMAT = "keymgr-export-v1"
_ENVELOPE_VERSION = 1

_SCRYPT_N = 2 ** 14
_SCRYPT_R = 8
_SCRYPT_P = 1
_KEY_LEN = 32
_NONCE_LEN = 12


class BundleError(Exception):
    """Base class for bundle failures (all surfaced as 400)."""


class InvalidBundle(BundleError):
    """Malformed envelope, unsupported format/version, or missing fields."""


class WrongPassphrase(BundleError):
    """Authentication failed: wrong passphrase or tampered ciphertext."""


def _b64e(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


def _b64d(text) -> bytes:
    if not isinstance(text, str):
        raise InvalidBundle("field bundle must be a base64 string")
    try:
        return base64.urlsafe_b64decode(text + "=" * (-len(text) % 4))
    except (ValueError, TypeError) as exc:
        raise InvalidBundle("field bundle is not valid base64") from exc


def _derive_key(passphrase: str, salt: bytes) -> bytes:
    if not isinstance(passphrase, str) or not passphrase:
        raise InvalidBundle("field passphrase must be a non-empty string")
    kdf = Scrypt(
        salt=salt,
        length=_KEY_LEN,
        n=_SCRYPT_N,
        r=_SCRYPT_R,
        p=_SCRYPT_P,
    )
    return kdf.derive(passphrase.encode("utf-8"))


def seal_envelope(payload: dict, passphrase: str, format_tag: str) -> str:
    """Authenticated-encrypt a payload into an opaque base64 token.

    Shared by the single-key export and the tenant backup; the ``format_tag``
    both names the envelope and authenticates the ciphertext as AAD, so a
    bundle of one format can never be replayed as the other.
    """
    salt = os.urandom(16)
    nonce = os.urandom(_NONCE_LEN)
    key = _derive_key(passphrase, salt)
    plaintext = json.dumps(
        payload, separators=(",", ":"), sort_keys=True
    ).encode("utf-8")
    envelope = {
        "format": format_tag,
        "version": _ENVELOPE_VERSION,
        "kdf": "scrypt",
        "salt": _b64e(salt),
        "n": _SCRYPT_N,
        "r": _SCRYPT_R,
        "p": _SCRYPT_P,
        "nonce": _b64e(nonce),
        "data": _b64e(
            AESGCM(key).encrypt(nonce, plaintext, format_tag.encode("ascii"))
        ),
    }
    raw = json.dumps(envelope, separators=(",", ":"), sort_keys=True).encode("utf-8")
    return _b64e(raw)


def open_envelope(bundle: str, passphrase: str, format_tag: str) -> bytes:
    """Authenticate and decrypt an envelope, returning raw plaintext bytes.

    Raises WrongPassphrase for authentication failures and InvalidBundle for
    structural problems; shared by the single-key and the tenant formats.
    """
    params = _load_envelope(bundle, format_tag)
    if not isinstance(passphrase, str) or not passphrase:
        raise InvalidBundle("field passphrase must be a non-empty string")
    try:
        kdf = Scrypt(
            salt=params["salt"],
            length=_KEY_LEN,
            n=params["n"],
            r=params["r"],
            p=params["p"],
        )
        key = kdf.derive(passphrase.encode("utf-8"))
    except (TypeError, ValueError) as exc:
        raise InvalidBundle("invalid kdf parameters in field bundle") from exc
    try:
        return AESGCM(key).decrypt(
            params["nonce"], params["data"], format_tag.encode("ascii")
        )
    except InvalidTag as exc:
        raise WrongPassphrase(
            "field passphrase is incorrect or bundle is tampered"
        ) from exc


def encode_bundle(payload: dict, passphrase: str) -> str:
    """Authenticated-encrypt an export payload into an opaque base64 token."""
    return seal_envelope(payload, passphrase, FORMAT)


def _load_envelope(bundle: str, expected_format: str = FORMAT) -> dict:
    raw = _b64d(bundle)
    try:
        envelope = json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise InvalidBundle("field bundle does not contain valid JSON") from exc
    if not isinstance(envelope, dict):
        raise InvalidBundle("field bundle must be a JSON object")
    if envelope.get("format") != expected_format:
        raise InvalidBundle(
            "field format must be %r" % expected_format
        )
    if envelope.get("version") != _ENVELOPE_VERSION:
        raise InvalidBundle(
            "unsupported bundle version for field bundle: %r"
            % (envelope.get("version"),)
        )
    if envelope.get("kdf") != "scrypt":
        raise InvalidBundle("unsupported kdf for field bundle")
    for name in ("salt", "nonce", "data"):
        if not isinstance(envelope.get(name), str):
            raise InvalidBundle("missing or invalid field: %s" % name)
    try:
        params = {
            "salt": _b64d(envelope["salt"]),
            "nonce": _b64d(envelope["nonce"]),
            "data": _b64d(envelope["data"]),
            "n": int(envelope["n"]),
            "r": int(envelope["r"]),
            "p": int(envelope["p"]),
        }
    except (KeyError, TypeError, ValueError) as exc:
        raise InvalidBundle("missing or invalid field in bundle header") from exc
    # Only the one parameter set we emit is accepted; this also stops a
    # crafted envelope from requesting an unbounded amount of KDF memory.
    if (
        params["n"] != _SCRYPT_N
        or params["r"] != _SCRYPT_R
        or params["p"] != _SCRYPT_P
        or len(params["salt"]) != 16
        or len(params["nonce"]) != _NONCE_LEN
    ):
        raise InvalidBundle("unsupported kdf parameters for field bundle")
    return params


def _require(data: dict, field: str, types) -> object:
    if field not in data or not isinstance(data[field], types):
        kind = "string" if types is str else "value"
        raise InvalidBundle("field %s must be a %s" % (field, kind))
    return data[field]


def validate_provider_block(block, where: str):
    """Validate an optional KMS/HSM provenance block on one version.

    The block is ``{"provider_id", "handle", "encrypted_material"}``; every
    field must be a non-empty string. ``None``/absent is valid and means the
    version originated on the built-in local provider (``keymgr-export-v1``
    bundles emitted before the provider layer carry no such field). Returns
    the cleaned block or None for a legacy version.
    """
    if block is None:
        return None
    prefix = where + ".provider"
    if not isinstance(block, dict):
        raise InvalidBundle("field %s must be an object" % prefix)
    unknown = set(block) - {"provider_id", "handle", "encrypted_material"}
    if unknown:
        raise InvalidBundle(
            "unknown field %s.%s" % (prefix, sorted(unknown)[0])
        )
    clean = {}
    for name in ("provider_id", "handle", "encrypted_material"):
        value = block.get(name)
        if not isinstance(value, str) or not value:
            raise InvalidBundle(
                "field %s.%s must be a non-empty string" % (prefix, name)
            )
        clean[name] = value
    return clean


def validate_version(ver, where: str) -> dict:
    """Validate one versions[i] block; ``where`` names it in error messages."""
    if not isinstance(ver, dict):
        raise InvalidBundle("field %s must be an object" % where)
    number = ver.get("version")
    created_at = ver.get("created_at")
    algorithm = ver.get("algorithm")
    public_key = ver.get("public_key")
    private_material = ver.get("private_material")
    if not isinstance(number, int) or isinstance(number, bool) or number < 1:
        raise InvalidBundle(
            "field %s.version must be a positive integer" % where
        )
    if not isinstance(created_at, str) or not created_at:
        raise InvalidBundle("field %s.created_at must be a string" % where)
    if algorithm not in SUPPORTED_ALGORITHMS:
        raise InvalidBundle(
            "field %s.algorithm must be one of: %s"
            % (where, ", ".join(SUPPORTED_ALGORITHMS))
        )
    if public_key is not None and not isinstance(public_key, str):
        raise InvalidBundle(
            "field %s.public_key must be a string or null" % where
        )
    if not isinstance(private_material, str) or not private_material:
        raise InvalidBundle(
            "field %s.private_material must be a non-empty string" % where
        )
    provider = validate_provider_block(ver.get("provider"), where)
    return {
        "version": number,
        "created_at": created_at,
        "algorithm": algorithm,
        "public_key": public_key,
        "private_material": private_material,
        "provider": provider,
    }


def validate_revocation_fields(data: dict, where: str = "") -> dict:
    """Validate status/reason/operator/revoked_at and return them cleaned."""
    prefix = where + "." if where else ""
    status = _require(data, "status", str)
    if status not in ("active", "revoked"):
        raise InvalidBundle(
            "field %sstatus must be 'active' or 'revoked'" % prefix
        )
    reason = data.get("reason")
    operator = data.get("operator")
    revoked_at = data.get("revoked_at")
    if status == "revoked":
        for name, value in (
            ("reason", reason),
            ("operator", operator),
            ("revoked_at", revoked_at),
        ):
            if not isinstance(value, str) or not value:
                raise InvalidBundle(
                    "field %s%s must be a non-empty string for a revoked key"
                    % (prefix, name)
                )
    elif any(v is not None for v in (reason, operator, revoked_at)):
        raise InvalidBundle(
            "revocation fields must be null for an active key"
        )
    return {
        "status": status,
        "reason": reason,
        "operator": operator,
        "revoked_at": revoked_at,
    }


def validate_payload(data: dict) -> dict:
    """Validate the decrypted export payload and return a cleaned copy.

    Raises InvalidBundle naming the offending field on any structural
    problem or missing field.
    """
    if not isinstance(data, dict):
        raise InvalidBundle("bundle payload must be a JSON object")
    if data.get("format") != FORMAT:
        raise InvalidBundle("field format must be %r" % FORMAT)

    key_id = _require(data, "key_id", str)
    from .store import is_valid_key_id

    if not is_valid_key_id(key_id):
        raise InvalidBundle("field key_id must be a UUID4")
    label = _require(data, "label", str)

    versions = data.get("versions")
    if not isinstance(versions, list) or not versions:
        raise InvalidBundle("field versions must be a non-empty array")

    seen_versions = set()
    clean_versions = []
    for index, ver in enumerate(versions):
        where = "versions[%d]" % index
        clean = validate_version(ver, where)
        if clean["version"] in seen_versions:
            raise InvalidBundle(
                "field %s.version duplicates another version" % where
            )
        seen_versions.add(clean["version"])
        clean_versions.append(clean)

    current_version = data.get("current_version")
    expected_numbers = set(range(1, len(seen_versions) + 1))
    if seen_versions != expected_numbers:
        raise InvalidBundle(
            "field versions must be the contiguous sequence 1..N with no gaps"
        )
    if (
        not isinstance(current_version, int)
        or isinstance(current_version, bool)
        or current_version != len(clean_versions)
    ):
        raise InvalidBundle(
            "field current_version must point at the latest exported version"
        )
    clean_versions.sort(key=lambda v: v["version"])

    revocation = validate_revocation_fields(data)

    return {
        "format": FORMAT,
        "key_id": key_id,
        "label": label,
        "current_version": current_version,
        "reason": revocation["reason"],
        "operator": revocation["operator"],
        "revoked_at": revocation["revoked_at"],
        "status": revocation["status"],
        "versions": clean_versions,
    }


def decode_bundle(bundle: str, passphrase: str) -> dict:
    """Decrypt and validate a bundle.

    Raises WrongPassphrase for authentication failures (wrong passphrase or
    tampered ciphertext) and InvalidBundle for structural, format/version and
    missing-field problems.
    """
    plaintext = open_envelope(bundle, passphrase, FORMAT)
    try:
        data = json.loads(plaintext.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise InvalidBundle("bundle payload is not valid JSON") from exc
    return validate_payload(data)

"""Per-tenant action policies: validation, persistence and enforcement.

A policy document is a list of rules; each rule binds a ``subject`` (the
X-Operator-Id of the caller), a set of ``actions`` and an ``effect`` of
``allow`` or ``deny``. Enforcement, for one (tenant, subject, action):

* a tenant with no document is unrestricted (every action is allowed);
* among the rules whose subject equals the caller and whose actions contain
  the action, any ``deny`` wins over ``allow``;
* if no matching rule exists the action is denied (default deny).

Documents are stored as one JSON file per tenant, written through the same
outbox transaction as key records: the file first lands carrying the audit
event, the ledger append follows, then the marker is cleared; a crash in
between is repaired idempotently on the next open.
"""

import hashlib
import json
import os
import tempfile
import threading
from contextlib import contextmanager
from dataclasses import dataclass
from typing import Iterator, List, Optional

from . import audit as audit_mod
from .audit import AuditEvent, AuditLog, LedgerError

try:  # fcntl is POSIX-only; policy writes still work without it.
    import fcntl
except ImportError:  # pragma: no cover - non-POSIX platforms
    fcntl = None

# Actions a policy rule can govern. These are the same action names the audit
# ledger uses (the management actions policy_* are deliberately not governable).
POLICY_ACTIONS = (
    "create",
    "read",
    "rotate",
    "revoke",
    "import",
    "export",
    "migrate",
    "encrypt",
    "decrypt",
    "rewrap",
    "sign",
    "verify",
    "audit",
    "list",
)
EFFECTS = ("allow", "deny")
_POLICY_DIR = "policies"


class PolicyError(ValueError):
    """A policy document or rule failed validation (surfaced as 400)."""


@dataclass(frozen=True)
class Rule:
    """One policy rule: an effect on a set of actions for one subject."""

    subject: str
    actions: List[str]
    effect: str

    def to_json(self) -> dict:
        """Serialize to a plain dict; actions are emitted sorted."""
        return {
            "subject": self.subject,
            "actions": list(self.actions),
            "effect": self.effect,
        }

    @classmethod
    def from_json(cls, data: dict) -> "Rule":
        # Documents on disk were validated when written, but validate again
        # on the way in so a hand-edited file can never break enforcement.
        return validate_rule(data)

    def signature(self):
        """Dedup key: same subject/effect with the same unordered action set."""
        return self.subject, self.effect, frozenset(self.actions)


def validate_rule(raw, index: Optional[int] = None) -> Rule:
    """Validate one rule object; raise PolicyError naming the bad field.

    ``index`` prefixes field names with ``rules[i].`` when the rule comes from
    a document; a standalone rule names the bare fields.
    """
    where = "rules[%d]." % index if index is not None else ""

    def err(message: str) -> PolicyError:
        return PolicyError(message)

    if not isinstance(raw, dict):
        raise err("field %s must be an object" % (where.rstrip(".") if index is not None else "rule"))
    known = {"subject", "actions", "effect"}
    unknown = set(raw) - known
    if unknown:
        raise err(
            "unknown field %s%s"
            % (where, sorted(unknown)[0])
        )
    subject = raw.get("subject")
    if not isinstance(subject, str) or not subject:
        raise err("field %ssubject must be a non-empty string" % where)
    effect = raw.get("effect")
    if not isinstance(effect, str) or effect not in EFFECTS:
        raise err(
            "field %seffect must be one of: %s"
            % (where, ", ".join(EFFECTS))
        )
    actions = raw.get("actions")
    if not isinstance(actions, list) or not actions:
        raise err(
            "field %sactions must be a non-empty array" % where
        )
    clean_actions = []
    for action in actions:
        if not isinstance(action, str) or not action:
            raise err(
                "field %sactions must be non-empty strings" % where
            )
        if action not in POLICY_ACTIONS:
            raise err(
                "field %sactions has unknown action %r (allowed: %s)"
                % (where, action, ", ".join(POLICY_ACTIONS))
            )
        if action not in clean_actions:
            # Duplicates within one rule are dropped, not an error: the action
            # set is unordered, so ["read", "read"] carries no extra meaning.
            clean_actions.append(action)
    return Rule(subject=subject, actions=clean_actions, effect=effect)


def validate_rules(raw) -> List[Rule]:
    """Validate a full rules array; [] is valid and means default-deny."""
    if not isinstance(raw, list):
        raise PolicyError("field rules must be an array")
    rules: List[Rule] = []
    seen = set()
    for index, item in enumerate(raw):
        rule = validate_rule(item, index)
        if rule.signature() in seen:
            raise PolicyError(
                "field rules contains a duplicate rule at index %d "
                "(same subject, effect and unordered actions)" % index
            )
        seen.add(rule.signature())
        rules.append(rule)
    return rules


class PolicyStore:
    """File-backed per-tenant policy documents."""

    def __init__(self, data_dir: str, audit_log: Optional[AuditLog] = None) -> None:
        self.data_dir = data_dir
        self.dir_path = os.path.join(data_dir, _POLICY_DIR)
        os.makedirs(self.dir_path, exist_ok=True)
        self.audit = audit_log if audit_log is not None else AuditLog(data_dir)
        self._write_lock = threading.Lock()
        self._recover_pending_events()

    # -- on-disk shape -----------------------------------------------------
    def path_for(self, tenant_id: str) -> str:
        """Public accessor for a tenant's policy document path."""
        return self._path_for(tenant_id)

    def _path_for(self, tenant_id: str) -> str:
        # Tenant ids are free-form strings, so never use them as a filename:
        # key the file by a digest of the tenant instead.
        digest = hashlib.sha256(tenant_id.encode("utf-8")).hexdigest()
        return os.path.join(self.dir_path, digest + ".json")

    def _lock_path_for(self, tenant_id: str) -> str:
        digest = hashlib.sha256(tenant_id.encode("utf-8")).hexdigest()
        return os.path.join(self.dir_path, digest + ".lock")

    @contextmanager
    def tenant_lock(
        self, tenant_id: str, timeout: Optional[float] = None
    ) -> Iterator[None]:
        """Serialize all writes to one tenant's policy across processes.

        Pairs the in-process write lock with an exclusive ``fcntl`` lock on a
        per-tenant sidecar file, so a put/delete/restore/backup in another
        process cannot interleave with this one's read-modify-write. With a
        finite ``timeout`` (idempotent restore) the wait is bounded and raises
        :class:`~keymgr.store.LockTimeout` when it elapses.
        """
        import time as _time

        from .store import LockTimeout

        deadline = None if timeout is None else _time.monotonic() + timeout
        if timeout is None:
            self._write_lock.acquire()
        else:
            if not self._write_lock.acquire(timeout=max(timeout, 0.0)):
                raise LockTimeout("policy:" + tenant_id)
        if fcntl is None:  # pragma: no cover - non-POSIX platforms
            try:
                yield
            finally:
                self._write_lock.release()
            return
        fd = os.open(
            self._lock_path_for(tenant_id), os.O_RDWR | os.O_CREAT, 0o600
        )
        acquired = False
        try:
            if deadline is None:
                fcntl.flock(fd, fcntl.LOCK_EX)
            else:
                while True:
                    try:
                        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                        break
                    except BlockingIOError:
                        remaining = deadline - _time.monotonic()
                        if remaining <= 0:
                            raise LockTimeout("policy:" + tenant_id)
                        _time.sleep(min(0.02, remaining))
            acquired = True
            yield
        finally:
            if acquired:
                fcntl.flock(fd, fcntl.LOCK_UN)
            os.close(fd)
            self._write_lock.release()

    def _write_atomic(self, path: str, payload: dict) -> None:
        fd, tmp_path = tempfile.mkstemp(dir=self.dir_path, suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                json.dump(payload, fh)
                fh.flush()
                os.fsync(fh.fileno())
            os.chmod(tmp_path, 0o600)
            os.replace(tmp_path, path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

    def _read_doc(self, path: str):
        """Return (tenant_id, rules, pending_event), or None if unreadable."""
        try:
            with open(path, "r", encoding="utf-8") as fh:
                data = json.load(fh)
        except (OSError, ValueError):
            return None
        try:
            rules = [Rule.from_json(r) for r in data["rules"]]
            return data["tenant_id"], rules, data.get("pending_event")
        except (KeyError, TypeError, ValueError, PolicyError):
            return None

    def _recover_pending_events(self) -> None:
        """Commit outbox events left pending by a crashed process."""
        try:
            names = os.listdir(self.dir_path)
        except OSError:
            return
        for name in names:
            if not name.endswith(".json") and not name.endswith(".json.del"):
                continue
            path = os.path.join(self.dir_path, name)
            doc = self._read_doc(path)
            if doc is None:
                continue
            tenant_id, rules, pending_event = doc
            if not pending_event:
                # A tombstone left behind after a successful ledger append:
                # finish the delete.
                if name.endswith(".del"):
                    try:
                        os.unlink(path)
                    except OSError:
                        pass
                continue
            # A multi-file tenant restore transaction is resolved by the
            # RestoreCoordinator (its manifest drives the shared event).
            if isinstance(pending_event, dict) and pending_event.get("_restore"):
                continue
            event = AuditEvent.from_json(pending_event)
            if name.endswith(".json.del"):                # A delete tombstone. If the original file is still on disk the
                # crash happened before the unlink, so the delete never
                # happened: discard the tombstone without appending. Otherwise
                # finish the transaction (append is idempotent on event_id).
                original = path[: -len(".del")]
                if os.path.exists(original):
                    try:
                        os.unlink(path)
                    except OSError:
                        pass
                    continue
                self.audit.append(event)
                try:
                    os.unlink(path)
                except OSError:
                    pass
            else:
                # append() is idempotent on event_id.
                self.audit.append(event)
                self._write_atomic(
                    path,
                    {"tenant_id": tenant_id,
                     "rules": [r.to_json() for r in rules],
                     "pending_event": None},
                )

    def _commit_put(self, tenant_id: str, rules: List[Rule],
                    event: AuditEvent, existed: bool, previous: Optional[dict]):
        """Write a document and its event as one logical transaction."""
        path = self._path_for(tenant_id)
        doc = {
            "tenant_id": tenant_id,
            "rules": [r.to_json() for r in rules],
            "pending_event": event.to_json(),
        }
        self._write_atomic(path, doc)
        try:
            self.audit.append(event)
        except BaseException:
            if not existed:
                try:
                    os.unlink(path)
                except OSError:
                    pass
            elif previous is not None:
                self._write_atomic(path, previous)
            raise
        # The durable ledger append is the commit point; clearing the marker
        # is post-commit housekeeping. A failure here leaves the marker for
        # startup recovery and must never roll the document back or fail the
        # request.
        doc["pending_event"] = None
        try:
            self._write_atomic(path, doc)
        except OSError:
            pass

    # -- public API --------------------------------------------------------
    def get(self, tenant_id: str) -> Optional[List[Rule]]:
        """Return the tenant's rules, or None when no document exists."""
        doc = self._read_doc(self._path_for(tenant_id))
        if doc is None:
            return None
        return doc[1]

    def put(self, tenant_id: str, rules: List[Rule]) -> List[Rule]:
        """Replace (or create) the tenant's document and audit policy_update."""
        with self.tenant_lock(tenant_id):
            path = self._path_for(tenant_id)
            existed = os.path.exists(path)
            previous = None
            if existed:
                try:
                    with open(path, "r", encoding="utf-8") as fh:
                        previous = json.load(fh)
                except (OSError, ValueError) as exc:
                    raise LedgerError(
                        "cannot read policy document: %s" % exc
                    ) from exc
            event = self.audit.new_event(
                tenant_id, audit_mod.ACTION_POLICY_UPDATE, None,
                audit_mod.OUTCOME_SUCCESS,
            )
            self._commit_put(tenant_id, rules, event, existed, previous)
        return rules

    def delete(self, tenant_id: str) -> None:
        """Delete the tenant's document and audit policy_delete.

        Tombstone sequence: write a ``.json.del`` marker carrying the event,
        unlink the document, append the event, then remove the marker. A crash
        between any two steps is repaired on the next open. If the ledger
        append itself fails, the original document is restored byte-for-byte
        and the tombstone discarded, so a failed delete never takes effect.
        Deleting a tenant that has no document still records the event.
        """
        with self.tenant_lock(tenant_id):
            path = self._path_for(tenant_id)
            existed = os.path.exists(path)
            event = self.audit.new_event(
                tenant_id, audit_mod.ACTION_POLICY_DELETE, None,
                audit_mod.OUTCOME_SUCCESS,
            )
            if not existed:
                self.audit.append(event)
                return
            try:
                with open(path, "r", encoding="utf-8") as fh:
                    previous = json.load(fh)
            except (OSError, ValueError) as exc:
                raise LedgerError(
                    "cannot read policy document: %s" % exc
                ) from exc
            tombstone = path + ".del"
            self._write_atomic(
                tombstone,
                {"tenant_id": tenant_id, "rules": [],
                 "pending_event": event.to_json()},
            )
            os.unlink(path)
            try:
                # From here on a crash is repaired from the tombstone; the
                # append is idempotent on event_id.
                self.audit.append(event)
            except BaseException:
                # The ledger write failed: roll the delete back so the
                # document and its event never diverge.
                self._write_atomic(path, previous)
                try:
                    os.unlink(tombstone)
                except OSError:
                    pass
                raise
            try:
                os.unlink(tombstone)
            except OSError:
                pass

    def audit_read(self, tenant_id: str) -> None:
        """Record a successful policy_read (the document is never modified)."""
        event = self.audit.new_event(
            tenant_id, audit_mod.ACTION_POLICY_READ, None,
            audit_mod.OUTCOME_SUCCESS,
        )
        self.audit.append(event)

    def is_allowed(self, tenant_id: str, action: str, subject: str) -> bool:
        """Enforce the tenant document for (subject, action).

        No document means unrestricted. Otherwise deny wins, and an action no
        rule matches is denied.
        """
        rules = self.get(tenant_id)
        if rules is None:
            return True
        allowed = False
        for rule in rules:
            if rule.subject != subject or action not in rule.actions:
                continue
            if rule.effect == "deny":
                return False
            allowed = True
        return allowed

    # -- tenant restore hooks ---------------------------------------------
    def owner_of_path(self, path: str) -> Optional[str]:
        """Return the owning tenant_id recorded inside a policy file."""
        doc = self._read_doc(path)
        if doc is None:
            return None
        return doc[0]

    def write_restore_pending(
        self, tenant_id: str, rules: List[Rule], marker: dict
    ) -> None:
        """Atomically write a restored policy document carrying the marker.

        Used by the RestoreCoordinator; the caller guarantees no document
        exists for the tenant and holds the write lock.
        """
        self._write_atomic(
            self._path_for(tenant_id),
            {
                "tenant_id": tenant_id,
                "rules": [r.to_json() for r in rules],
                "pending_event": marker,
            },
        )

    def clear_restore_pending(self, tenant_id: str, rules: List[Rule]) -> None:
        """Rewrite a restored policy document without its pending marker."""
        self._write_atomic(
            self._path_for(tenant_id),
            {
                "tenant_id": tenant_id,
                "rules": [r.to_json() for r in rules],
                "pending_event": None,
            },
        )

    def remove_restore_file(self, tenant_id: str) -> None:
        """Delete a policy document written by a restore being rolled back."""
        try:
            os.unlink(self._path_for(tenant_id))
        except FileNotFoundError:
            pass

"""Authenticated passphrase encryption for tenant backup/restore bundles.

A tenant bundle is an opaque, single base64 token using the same scrypt +
AES-256-GCM envelope (and the same fixed cost parameters) as a single-key
export; only the authenticated format tag differs, so a backup and an export
bundle can never be replayed for one another. Its plaintext carries the whole
tenant::

    {format, tenant_id, keys, policy}

``keys`` is a list of per-key projections (``key_id``, ``label``,
``current_version``, ``status``, ``reason``, ``operator``, ``revoked_at`` and
every ``versions`` entry with public and private material); ``policy`` is
either null or ``{"rules": [...]}``. Private key material only ever exists
sealed inside the authenticated bundle.
"""

import json

from . import keybundle
from .keybundle import seal_envelope, open_envelope, validate_version
from .policy import PolicyError, validate_rules
from .store import is_valid_key_id

FORMAT = "tenant-backup-v1"


class TenantBundleError(Exception):
    """Base class for tenant bundle failures (all surfaced as 400)."""


class InvalidTenantBundle(TenantBundleError):
    """Malformed envelope, unsupported format/version, or missing fields."""


class WrongTenantPassphrase(TenantBundleError):
    """Authentication failed: wrong passphrase or tampered ciphertext."""


def _require(data: dict, field: str, types) -> object:
    if field not in data or not isinstance(data[field], types):
        kind = "string" if types is str else "value"
        raise InvalidTenantBundle("field %s must be a %s" % (field, kind))
    return data[field]


def encode_bundle(payload: dict, passphrase: str) -> str:
    """Authenticated-encrypt a tenant backup payload into an opaque token."""
    return seal_envelope(payload, passphrase, FORMAT)


def _validate_key(item, index: int) -> dict:
    """Validate one keys[i] entry of a tenant backup payload."""
    where = "keys[%d]" % index
    if not isinstance(item, dict):
        raise InvalidTenantBundle("field %s must be an object" % where)
    key_id = item.get("key_id")
    if not is_valid_key_id(key_id):
        raise InvalidTenantBundle("field %s.key_id must be a UUID4" % where)
    label = item.get("label")
    if not isinstance(label, str):
        raise InvalidTenantBundle("field %s.label must be a string" % where)

    versions = item.get("versions")
    if not isinstance(versions, list) or not versions:
        raise InvalidTenantBundle(
            "field %s.versions must be a non-empty array" % where
        )
    seen_versions = set()
    clean_versions = []
    for v_index, ver in enumerate(versions):
        v_where = "%s.versions[%d]" % (where, v_index)
        # The per-version checks are shared with the single-key format; their
        # InvalidBundle wording already names the offending field.
        try:
            clean = validate_version(ver, v_where)
        except keybundle.InvalidBundle as exc:
            raise InvalidTenantBundle(str(exc)) from exc
        if clean["version"] in seen_versions:
            raise InvalidTenantBundle(
                "field %s.version duplicates another version" % v_where
            )
        seen_versions.add(clean["version"])
        clean_versions.append(clean)
    expected = set(range(1, len(seen_versions) + 1))
    if seen_versions != expected:
        raise InvalidTenantBundle(
            "field %s.versions must be the contiguous sequence 1..N "
            "with no gaps" % where
        )
    clean_versions.sort(key=lambda v: v["version"])
    current_version = item.get("current_version")
    if (
        not isinstance(current_version, int)
        or isinstance(current_version, bool)
        or current_version != len(clean_versions)
    ):
        raise InvalidTenantBundle(
            "field %s.current_version must point at the latest version"
            % where
        )

    try:
        revocation = keybundle.validate_revocation_fields(item, where)
    except keybundle.InvalidBundle as exc:
        raise InvalidTenantBundle(str(exc)) from exc

    return {
        "key_id": key_id,
        "label": label,
        "current_version": current_version,
        "status": revocation["status"],
        "reason": revocation["reason"],
        "operator": revocation["operator"],
        "revoked_at": revocation["revoked_at"],
        "versions": clean_versions,
    }


def _validate_policy(raw) -> object:
    """Validate the policy slot: None, or an object {"rules": [...]}."""
    if raw is None:
        return None
    if not isinstance(raw, dict):
        raise InvalidTenantBundle("field policy must be an object or null")
    unknown = set(raw) - {"rules"}
    if unknown:
        raise InvalidTenantBundle(
            "unknown field %s in policy" % sorted(unknown)[0]
        )
    if "rules" not in raw:
        raise InvalidTenantBundle("missing required field: policy.rules")
    try:
        rules = validate_rules(raw["rules"])
    except PolicyError as exc:
        raise InvalidTenantBundle(str(exc)) from exc
    return {"rules": [r.to_json() for r in rules]}


def validate_payload(data: dict) -> dict:
    """Validate the decrypted tenant payload and return a cleaned copy.

    Raises InvalidTenantBundle naming the offending field on any structural
    problem or missing field.
    """
    if not isinstance(data, dict):
        raise InvalidTenantBundle("bundle payload must be a JSON object")
    if data.get("format") != FORMAT:
        raise InvalidTenantBundle("field format must be %r" % FORMAT)
    tenant_id = _require(data, "tenant_id", str)
    if not tenant_id:
        raise InvalidTenantBundle("field tenant_id must be a non-empty string")

    keys = data.get("keys")
    if not isinstance(keys, list):
        raise InvalidTenantBundle("field keys must be an array")
    seen_key_ids = set()
    clean_keys = []
    for index, item in enumerate(keys):
        clean = _validate_key(item, index)
        if clean["key_id"] in seen_key_ids:
            raise InvalidTenantBundle(
                "field keys[%d].key_id duplicates another key" % index
            )
        seen_key_ids.add(clean["key_id"])
        clean_keys.append(clean)

    if "policy" not in data:
        raise InvalidTenantBundle("missing required field: policy")
    policy = _validate_policy(data["policy"])

    return {
        "format": FORMAT,
        "tenant_id": tenant_id,
        "keys": clean_keys,
        "policy": policy,
    }


def decode_bundle(bundle: str, passphrase: str) -> dict:
    """Decrypt and validate a tenant backup bundle.

    Raises WrongTenantPassphrase for authentication failures (wrong
    passphrase or tampered ciphertext) and InvalidTenantBundle for
    structural, format/version and missing-field problems.
    """
    try:
        plaintext = open_envelope(bundle, passphrase, FORMAT)
    except keybundle.WrongPassphrase as exc:
        raise WrongTenantPassphrase(str(exc)) from exc
    except keybundle.InvalidBundle as exc:
        raise InvalidTenantBundle(str(exc)) from exc
    try:
        data = json.loads(plaintext.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise InvalidTenantBundle("bundle payload is not valid JSON") from exc
    return validate_payload(data)

